#!/usr/bin/env python3
import sys

B_S = (512, 1024, 2048)
B_P = (0, 512, 1024)


def first_ge(buckets, need):
    for b in buckets:
        if b >= need:
            return b
    return None


def select_context(requests, b_s_buckets=B_S, b_p_buckets=B_P):
    if not requests:
        return {'ok': False, 'reason': 'empty'}
    for item in requests:
        if len(item) != 2:
            return {'ok': False, 'reason': 'shape'}
        L, h = item
        if L < 0 or h < 0 or h > L:
            return {'ok': False, 'reason': 'range'}
    suffixes = [L - h for L, h in requests]
    if max(suffixes) == 0:
        return {'ok': True, 'mode': 'full_hit', 'b_s': 0, 'b_p': 0, 'rows': []}
    b_s = first_ge(b_s_buckets, max(suffixes))
    if b_s is None:
        return {'ok': False, 'reason': 'no_suffix_bucket'}
    provisional = []
    for L, h in requests:
        s = L - h
        slack = b_s - s
        m = min(h, slack)
        a = h - m
        s_prime = s + m
        if a + s_prime != L:
            return {'ok': False, 'reason': 'invariant'}
        provisional.append((L, h, m, a, s_prime))
    max_a = max(row[3] for row in provisional)
    b_p = first_ge(b_p_buckets, max_a)
    if b_p is None:
        return {'ok': False, 'reason': 'no_prefix_bucket', 'b_s': b_s, 'max_a': max_a}
    rows = []
    for L, h, m, a, s_prime in provisional:
        pad_s = b_s - s_prime
        pad_p = b_p - a
        if pad_s < 0 or pad_p < 0:
            return {'ok': False, 'reason': 'negative_padding'}
        rows.append({'L': L, 'h': h, 'm': m, 'a': a, 's_prime': s_prime,
                     'pad_s': pad_s, 'pad_p': pad_p})
    return {'ok': True, 'mode': 'context', 'b_s': b_s, 'b_p': b_p, 'rows': rows}


def buggy_select_context(requests):
    if not requests:
        return {'ok': False, 'reason': 'empty'}
    for L, h in requests:
        if L < 0 or h < 0 or h > L:
            return {'ok': False, 'reason': 'range'}
    b_s = first_ge(B_S, max(L for L, h in requests))
    if b_s is None:
        return {'ok': False, 'reason': 'no_suffix_bucket'}
    max_a = max(h for L, h in requests)
    b_p = first_ge(B_P, max_a)
    if b_p is None:
        return {'ok': False, 'reason': 'no_prefix_bucket'}
    rows = []
    for L, h in requests:
        rows.append({'L': L, 'h': h, 'm': 0, 'a': h, 's_prime': L - h,
                     'pad_s': b_s - (L - h), 'pad_p': b_p - h})
    return {'ok': True, 'mode': 'context', 'b_s': b_s, 'b_p': b_p, 'rows': rows}


def qk_pairs(a, s):
    if a < 0 or s < 0:
        raise ValueError('negative_length')
    return a * s + s * (s + 1) // 2


def bucket_pairs(b_p, b_s):
    if b_p < 0 or b_s < 0:
        raise ValueError('negative_bucket')
    return b_p * b_s + b_s * (b_s + 1) // 2


def buggy_qk_pairs(a, s):
    return a * s + s * s // 2


def check_context(name, requests, expected, failures, observations):
    got = select_context(requests)
    if expected is None:
        if got['ok']:
            failures.append(name + ': expected failure, got success')
            return
        observations.append(name + ': failure=' + got.get('reason', 'unknown'))
        return
    if not got['ok']:
        failures.append(name + ': unexpected failure ' + got.get('reason', 'unknown'))
        return
    for key, value in expected.items():
        if key == 'rows':
            continue
        if got.get(key) != value:
            failures.append(name + ': ' + key + ' expected ' + repr(value) + ' got ' + repr(got.get(key)))
            return
    expected_rows = expected.get('rows', [])
    if len(expected_rows) != len(got['rows']):
        failures.append(name + ': row count differs')
        return
    for idx, exp_row in enumerate(expected_rows):
        got_row = got['rows'][idx]
        for key, value in exp_row.items():
            if got_row.get(key) != value:
                failures.append(name + ': row ' + str(idx) + ' ' + key + ' expected ' + repr(value) + ' got ' + repr(got_row.get(key)))
                return
    for row in got['rows']:
        L = row['L']
        h = row['h']
        if row['a'] + row['s_prime'] != L:
            failures.append(name + ': prefix plus suffix does not preserve length')
            return
        if row['m'] + row['a'] != h:
            failures.append(name + ': moved plus kept prefix does not equal hit')
            return
        if row['m'] < 0 or row['m'] > h:
            failures.append(name + ': invalid movement')
            return
        if row['s_prime'] > got['b_s'] or row['a'] > got['b_p']:
            failures.append(name + ': bucket does not cover effective lengths')
            return
        if row['pad_s'] < 0 or row['pad_p'] < 0:
            failures.append(name + ': negative padding')
            return
    observations.append(name + ': ok b_s=' + str(got['b_s']) + ' b_p=' + str(got['b_p']))


def main():
    failures = []
    observations = []

    check_context('no_prefix_1000', [(1000, 0)],
                  {'mode': 'context', 'b_s': 1024, 'b_p': 0,
                   'rows': [{'m': 0, 'a': 0, 's_prime': 1000, 'pad_s': 24, 'pad_p': 0}]},
                  failures, observations)
    check_context('move_all_prefix_800', [(800, 128)],
                  {'mode': 'context', 'b_s': 1024, 'b_p': 0,
                   'rows': [{'m': 128, 'a': 0, 's_prime': 800, 'pad_s': 224, 'pad_p': 0}]},
                  failures, observations)
    check_context('move_tail_900', [(900, 640)],
                  {'mode': 'context', 'b_s': 512, 'b_p': 512,
                   'rows': [{'m': 252, 'a': 388, 's_prime': 512, 'pad_s': 0, 'pad_p': 124}]},
                  failures, observations)
    check_context('prefix_overflow_1600', [(1600, 1280)], None, failures, observations)
    check_context('exact_suffix_bucket', [(512, 0)],
                  {'mode': 'context', 'b_s': 512, 'b_p': 0,
                   'rows': [{'m': 0, 'a': 0, 's_prime': 512, 'pad_s': 0, 'pad_p': 0}]},
                  failures, observations)
    check_context('full_hit_skip', [(128, 128)],
                  {'mode': 'full_hit', 'b_s': 0, 'b_p': 0, 'rows': []},
                  failures, observations)
    check_context('batch_uses_largest_suffix', [(800, 128), (900, 640)],
                  {'mode': 'context', 'b_s': 1024, 'b_p': 512,
                   'rows': [{'m': 128, 'a': 0, 's_prime': 800, 'pad_s': 224, 'pad_p': 512},
                            {'m': 260, 'a': 380, 's_prime': 520, 'pad_s': 504, 'pad_p': 132}]},
                  failures, observations)
    check_context('long_prompt_2000', [(2000, 100)],
                  {'mode': 'context', 'b_s': 2048, 'b_p': 0,
                   'rows': [{'m': 100, 'a': 0, 's_prime': 2000, 'pad_s': 48, 'pad_p': 0}]},
                  failures, observations)

    if qk_pairs(388, 512) != 329984:
        failures.append('qk_pairs 388/512 mismatch')
    if qk_pairs(640, 260) != 200330:
        failures.append('qk_pairs 640/260 mismatch')
    if qk_pairs(0, 1) != 1 or qk_pairs(1, 0) != 0:
        failures.append('qk_pairs edge case mismatch')
    if bucket_pairs(512, 512) != 393472:
        failures.append('bucket_pairs 512/512 mismatch')
    if bucket_pairs(1024, 1024) != 1573376:
        failures.append('bucket_pairs 1024/1024 mismatch')

    if buggy_qk_pairs(7, 5) == qk_pairs(7, 5):
        failures.append('negative control qk formula was not detected')
    else:
        observations.append('negative control qk formula detected: ' + str(buggy_qk_pairs(7, 5)) + ' vs ' + str(qk_pairs(7, 5)))

    bad = buggy_select_context([(900, 640)])
    good = select_context([(900, 640)])
    if not bad['ok'] or bad['b_s'] == good['b_s'] and bad['b_p'] == good['b_p']:
        failures.append('negative control bucket selector was not detected')
    else:
        observations.append('negative control bucket selector detected: b_s ' + str(bad['b_s']) + ' vs ' + str(good['b_s']) + ', b_p ' + str(bad['b_p']) + ' vs ' + str(good['b_p']))

    for line in observations:
        print('OBS ' + line)
    if failures:
        for line in failures:
            print('FAIL ' + line)
        print('RESULT FAIL')
        return 1
    print('RESULT PASS')
    return 0


if __name__ == '__main__':
    sys.exit(main())
